  var x0=up[1]*z2-up[2]*z1, x1=up[2]*z0-up[0]*z2, x2=up[0]*z1-up[1]*z0;
  len=Math.hypot(x0,x1,x2);
  if(len < 1e-6){ x0=1; x1=0; x2=0; } else { x0/=len; x1/=len; x2/=len; }
  var y0=z1*x2-z2*x1, y1=z2*x0-z0*x2, y2=z0*x1-z1*x0;
  out[0]=x0; out[1]=y0; out[2]=z0; out[3]=0;
  out[4]=x1; out[5]=y1; out[6]=z1; out[7]=0;
  out[8]=x2; out[9]=y2; out[10]=z2; out[11]=0;
  out[12]=-(x0*eye[0]+x1*eye[1]+x2*eye[2]);
  out[13]=-(y0*eye[0]+y1*eye[1]+y2*eye[2]);
  out[14]=-(z0*eye[0]+z1*eye[1]+z2*eye[2]);
  out[15]=1;
  return out;
}
function smoothstep(a,b,x){
  x = Math.max(0, Math.min(1, (x-a)/(b-a)));
  return x*x*(3-2*x);
}

/* -------------------------------------------------------------- geometry */
function computeNormals(positions, indices){
  var n = new Array(positions.length);
  for(var i=0;i<n.length;i++) n[i]=0;
  for(var k=0;k<indices.length;k+=3){
    var a=indices[k]*3, b=indices[k+1]*3, c=indices[k+2]*3;
    var e1x=positions[b]-positions[a], e1y=positions[b+1]-positions[a+1], e1z=positions[b+2]-positions[a+2];
    var e2x=positions[c]-positions[a], e2y=positions[c+1]-positions[a+1], e2z=positions[c+2]-positions[a+2];
    var nx=e1y*e2z-e1z*e2y, ny=e1z*e2x-e1x*e2z, nz=e1x*e2y-e1y*e2x;
    n[a]+=nx; n[a+1]+=ny; n[a+2]+=nz;
    n[b]+=nx; n[b+1]+=ny; n[b+2]+=nz;
    n[c]+=nx; n[c+1]+=ny; n[c+2]+=nz;
  }
  for(var j=0;j<n.length;j+=3){
    var l=Math.hypot(n[j],n[j+1],n[j+2])||1e-9;
    n[j]/=l; n[j+1]/=l; n[j+2]/=l;
  }
  return n;
}
/* Ensure triangle winding (hence GL front faces) and normals point away from
   the given interior point, so CCW-front-face culling keeps outer surfaces. */
function ensureOutward(geo, cx, cy, cz){
  var dot=0;
  for(var i=0;i<geo.positions.length;i+=3){
    dot += geo.normals[i]*(geo.positions[i]-cx)
         + geo.normals[i+1]*(geo.positions[i+1]-cy)
         + geo.normals[i+2]*(geo.positions[i+2]-cz);
  }
  if(dot < 0){
    for(var j=0;j<geo.normals.length;j++) geo.normals[j] = -geo.normals[j];
    for(var k=0;k<geo.indices.length;k+=3){
      var t=geo.indices[k+1]; geo.indices[k+1]=geo.indices[k+2]; geo.indices[k+2]=t;
    }
  }
}
function createSphere(radius, lat, lon){
  var positions=[], colors=[], indices=[], i, j;
  for(i=0;i<=lat;i++){
    var theta=i/lat*Math.PI, st=Math.sin(theta), ct=Math.cos(theta);
    for(j=0;j<=lon;j++){
      var phi=j/lon*Math.PI*2;
      positions.push(Math.sin(phi)*st*radius, ct*radius, Math.cos(phi)*st*radius);
      colors.push(1,1,1);
    }
  }
  for(i=0;i<lat;i++){
    for(j=0;j<lon;j++){
      var a=i*(lon+1)+j, b=a+(lon+1), c=a+1, d=b+1;
      indices.push(a,b,c, b,d,c);
    }
  }
  var geo={positions:positions, normals:computeNormals(positions,indices), colors:colors, indices:indices};
  ensureOutward(geo, 0,0,0);
  return geo;
}
/* A faceted, ridged cone used for the mountain and the pine trees. */
function createPeak(o){
  var baseR=o.baseR, height=o.height, rings=o.rings, segs=o.segs;
  var yBase=o.yBase||0, ox=o.ox||0, oz=o.oz||0;
  var noise=(o.noise===undefined?0.12:o.noise), pw=(o.pow===undefined?0.75:o.pow);
  var colorFn=o.colorFn;
  var positions=[], colors=[], indices=[], i, j;
  for(i=0;i<=rings;i++){
    var h=i/rings, y=yBase+h*height, prof=Math.pow(1-h, pw);
    for(j=0;j<=segs;j++){
      var phi=j/segs*Math.PI*2;
      var ridge = Math.sin(phi*3.0)*0.5 + Math.sin(phi*5.0+1.7)*0.28
                + Math.sin(phi*9.0+0.4)*0.14 + Math.sin(phi*17.0+2.2)*0.06;
      var amt = noise*Math.sin(h*Math.PI)*0.9;
      var r = baseR*prof*(1.0 + ridge*amt);
      var yy = y + Math.sin(phi*4.0+h*9.0)*0.012*(noise/0.12)*Math.min(1, h*4);
      positions.push(ox+Math.cos(phi)*r, yy, oz+Math.sin(phi)*r);
      var c=colorFn(h, phi, r);
      colors.push(c[0],c[1],c[2]);
    }
  }
  for(i=0;i<rings;i++){
    for(j=0;j<segs;j++){
      var a=i*(segs+1)+j, b=a+(segs+1), cc=a+1, d=b+1;
      indices.push(a,b,cc, b,d,cc);
    }
  }
  var geo={positions:positions, normals:computeNormals(positions,indices), colors:colors, indices:indices};
  ensureOutward(geo, ox, yBase+height*0.30, oz);
  return geo;
}
function createLathe(profile, segs, colorFn){
  var positions=[], colors=[], indices=[], i, j;
  for(i=0;i<profile.length;i++){
    var r=profile[i][0], y=profile[i][1];
    for(j=0;j<=segs;j++){
      var phi=j/segs*Math.PI*2;
      positions.push(Math.cos(phi)*r, y, Math.sin(phi)*r);
      var c=colorFn(i/(profile.length-1), y, r);
      colors.push(c[0],c[1],c[2]);
    }
  }
  for(i=0;i<profile.length-1;i++){
    for(j=0;j<segs;j++){
      var a=i*(segs+1)+j, b=a+(segs+1), cc=a+1, d=b+1;
      indices.push(a,b,cc, b,d,cc);
    }
  }
  var ySum=0; for(i=0;i<profile.length;i++) ySum+=profile[i][1];
  var geo={positions:positions, normals:computeNormals(positions,indices), colors:colors, indices:indices};
  ensureOutward(geo, 0, ySum/profile.length, 0);
  return geo;
}
function transformGeo(geo, sx, sy, sz, dx, dy, dz){
  for(var i=0;i<geo.positions.length;i+=3){
    geo.positions[i]   = geo.positions[i]*sx + dx;
    geo.positions[i+1] = geo.positions[i+1]*sy + dy;
    geo.positions[i+2] = geo.positions[i+2]*sz + dz;
  }
  geo.normals = computeNormals(geo.positions, geo.indices);
  return geo;
}

/* ---------------------------------------------------------------- shaders */
function compileShader(type, src){
  var sh=gl.createShader(type);
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if(!gl.getShaderParameter(sh, gl.COMPILE_STATUS)){
    console.error('Shader error: ' + gl.getShaderInfoLog(sh));
  }
  return sh;
}
function makeProgram(vsSrc, fsSrc){
  var p=gl.createProgram();
  gl.attachShader(p, compileShader(gl.VERTEX_SHADER, vsSrc));
  gl.attachShader(p, compileShader(gl.FRAGMENT_SHADER, fsSrc));
  gl.linkProgram(p);
  if(!gl.getProgramParameter(p, gl.LINK_STATUS)) console.error('Link error: ' + gl.getProgramInfoLog(p));
  return p;
}

var LIT_VS = [
'attribute vec3 aPosition;',
'attribute vec3 aNormal;',
'attribute vec3 aColor;',
'uniform mat4 uView;',
'uniform mat4 uProj;',
'varying vec3 vNormal;',
'varying vec3 vPosition;',
'varying vec3 vColor;',
'void main(){',
'  vNormal = aNormal;',
'  vPosition = aPosition;',
'  vColor = aColor;',
'  gl_Position = uProj * uView * vec4(aPosition, 1.0);',
'}'].join('\n');

var LIT_FS = [
'precision highp float;',
'varying vec3 vNormal;',
'varying vec3 vPosition;',
'varying vec3 vColor;',
'uniform vec3 uLightDir;',
'uniform vec3 uCameraPos;',
'uniform float uAlpha;',
'void main(){',
'  vec3 N = normalize(vNormal);',
'  vec3 L = normalize(uLightDir);',
'  vec3 V = normalize(uCameraPos - vPosition);',
'  float diff = max(dot(N, L), 0.0);',
'  float amb = 0.42 + 0.16 * max(N.y, 0.0);',
'  vec3 H = normalize(L + V);',
'  float spec = pow(max(dot(N, H), 0.0), 42.0);',
'  vec3 col = vColor * (amb + 0.70 * diff) + vec3(spec) * 0.25;',
'  gl_FragColor = vec4(col, uAlpha);',
'}'].join('\n');

var GLASS_VS = [
'attribute vec3 aPosition;',
'attribute vec3 aNormal;',
'uniform mat4 uView;',
'uniform mat4 uProj;',
'varying vec3 vNormal;',
'varying vec3 vPosition;',
'void main(){',
'  vNormal = aNormal;',
'  vPosition = aPosition;',
'  gl_Position = uProj * uView * vec4(aPosition, 1.0);',
'}'].join('\n');

var GLASS_FS = [
'precision highp float;',
'varying vec3 vNormal;',
'varying vec3 vPosition;',
'uniform vec3 uLightDir;',
'uniform vec3 uCameraPos;',
'uniform float uAlpha;',
'void main(){',
'  vec3 N = normalize(vNormal);',
'  vec3 V = normalize(uCameraPos - vPosition);',
'  vec3 L = normalize(uLightDir);',
'  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.6);',
'  vec3 H = normalize(L + V);',
'  float spec = pow(max(dot(N, H), 0.0), 90.0);',
'  vec3 tint = vec3(0.68, 0.82, 0.95);',
'  vec3 col = tint * (0.22 + 0.90 * fres) + vec3(1.0) * spec;',
'  float a = uAlpha * (0.05 + 0.92 * fres) + spec * 0.85;',
'  gl_FragColor = vec4(col, clamp(a, 0.0, 1.0));',
'}'].join('\n');

var POINTS_VS = [
'attribute vec3 aPosition;',
'attribute float aSize;',
'uniform mat4 uView;',
'uniform mat4 uProj;',
'uniform float uFocal;',
'varying float vFade;',
'void main(){',
'  vec4 mv = uView * vec4(aPosition, 1.0);',
'  gl_Position = uProj * mv;',
'  float d = max(0.001, -mv.z);',
'  gl_PointSize = clamp(aSize * uFocal / d, 1.0, 26.0);',
'  vFade = clamp(1.15 - d * 0.22, 0.35, 1.0);',
'}'].join('\n');

var POINTS_FS = [
'precision mediump float;',
'varying float vFade;',
'void main(){',
'  vec2 c = gl_PointCoord * 2.0 - 1.0;',
'  float r2 = dot(c, c);',
'  if(r2 > 1.0) discard;',
'  float a = 1.0 - r2;',
'  gl_FragColor = vec4(1.0, 1.0, 1.0, a * a * 0.95 * vFade);',
'}'].join('\n');

var litProg   = makeProgram(LIT_VS, LIT_FS);
var glassProg = makeProgram(GLASS_VS, GLASS_FS);
var pointProg = makeProgram(POINTS_VS, POINTS_FS);

var litLoc = {
  aPos: gl.getAttribLocation(litProg,'aPosition'),
  aNor: gl.getAttribLocation(litProg,'aNormal'),
  aCol: gl.getAttribLocation(litProg,'aColor'),
  uView: gl.getUniformLocation(litProg,'uView'),
  uProj: gl.getUniformLocation(litProg,'uProj'),
  uLight: gl.getUniformLocation(litProg,'uLightDir'),
  uCam: gl.getUniformLocation(litProg,'uCameraPos'),
  uAlpha: gl.getUniformLocation(litProg,'uAlpha')
};
var glassLoc = {
  aPos: gl.getAttribLocation(glassProg,'aPosition'),
  aNor: gl.getAttribLocation(glassProg,'aNormal'),
  uView: gl.getUniformLocation(glassProg,'uView'),
  uProj: gl.getUniformLocation(glassProg,'uProj'),
  uLight: gl.getUniformLocation(glassProg,'uLightDir'),
  uCam: gl.getUniformLocation(glassProg,'uCameraPos'),
  uAlpha: gl.getUniformLocation(glassProg,'uAlpha')
};
var pointLoc = {
  aPos: gl.getAttribLocation(pointProg,'aPosition'),
  aSize: gl.getAttribLocation(pointProg,'aSize'),
  uView: gl.getUniformLocation(pointProg,'uView'),
  uProj: gl.getUniformLocation(pointProg,'uProj'),
  uFocal: gl.getUniformLocation(pointProg,'uFocal')
};

/* ----------------------------------------------------------- scene build */
var GLOBE_R = 1.0;
var MOUND = { yc:-0.52, yr:0.30, xr:0.72 };

function mountainColor(h, phi){
  var line = 0.54 + 0.06*Math.sin(phi*3.0+0.8) + 0.035*Math.sin(phi*7.0+2.0) + 0.035*Math.sin(h*9.0);
  var s = smoothstep(line-0.05, line+0.045, h);
  var rr = 0.30 + 0.06*Math.sin(phi*6.0);
  var gg = 0.275 + 0.05*Math.sin(phi*5.0+1.0);
  var bb = 0.335 + 0.05*Math.sin(phi*4.0+2.0);
  return [ rr*(1-s)+0.98*s, gg*(1-s)+0.99*s, bb*(1-s)+1.0*s ];
}
function treeColor(h, phi){
  var s = smoothstep(0.40, 0.78, h + 0.05*Math.sin(phi*3.0));
  var rr = 0.075*(1-s) + 0.90*s;
  var gg = 0.235*(1-s) + 0.94*s;
  var bb = 0.130*(1-s) + 0.96*s;
  return [rr, gg, bb];
}
function baseColor(t, y, r){
  if(y > -1.135 && y < -1.045) return [0.66, 0.50, 0.23];
  var shade = 0.085 + 0.05*t;
  return [shade, shade*1.03, shade*1.20];
}

var mountainGeo = createPeak({
  baseR:0.42, height:1.05, rings:34, segs:64, yBase:-0.38, noise:0.16, pow:0.78, colorFn:mountainColor
});
var moundGeo = transformGeo(createSphere(1.0, 26, 48), MOUND.xr, MOUND.yr, MOUND.xr, 0, MOUND.yc, 0);
for(var mi=0; mi<moundGeo.colors.length; mi+=3){
  var up = Math.max(0, moundGeo.normals[mi+1]);
  moundGeo.colors[mi]   = 0.820 + 0.15*up;
  moundGeo.colors[mi+1] = 0.875 + 0.11*up;
  moundGeo.colors[mi+2] = 0.960 + 0.04*up;
}

var baseProfile = [
  [0.00,-1.52],[0.80,-1.52],[0.87,-1.43],[0.85,-1.35],
  [0.68,-1.21],[0.58,-1.13],[0.615,-1.08],[0.565,-1.02],
  [0.42,-0.98],[0.345,-0.95],[0.00,-0.95]
];
var baseGeo = createLathe(baseProfile, 56, baseColor);

var treeGeos = [];
for(var k=0;k<7;k++){
  var ang = k/7*Math.PI*2 + 0.45;
  var dd = 0.545 + 0.05*Math.sin(k*2.1+0.7);
  var ty = MOUND.yc + MOUND.yr*Math.sqrt(Math.max(0, 1-(dd/MOUND.xr)*(dd/MOUND.xr)));
  var th = 0.235 + 0.075*Math.abs(Math.sin(k*1.7));
  treeGeos.push(createPeak({
    baseR:0.082 + 0.018*Math.abs(Math.cos(k*1.3)),
    height:th, rings:10, segs:18,
    yBase:ty-0.035, ox:Math.cos(ang)*dd, oz:Math.sin(ang)*dd,
    noise:0.055, pow:1.05, colorFn:treeColor
  }));
}

var globeGeo = createSphere(GLOBE_R, 40, 60);

/* ---------------------------------------------------------------- buffers */
function makeMesh(geo){
  var pos=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER,pos);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.positions),gl.STATIC_DRAW);
  var nor=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER,nor);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.normals),gl.STATIC_DRAW);
  var col=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER,col);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.colors),gl.STATIC_DRAW);
  var idx=gl.createBuffer();
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,idx);
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(geo.indices),gl.STATIC_DRAW);
  return {pos:pos, nor:nor, col:col, idx:idx, count:geo.indices.length};
}

var baseMesh = makeMesh(baseGeo);
var moundMesh = makeMesh(moundGeo);
var mountainMesh = makeMesh(mountainGeo);
var globeMesh = makeMesh(globeGeo);
var treeMeshes = [];
for(var tm=0; tm<treeGeos.length; tm++) treeMeshes.push(makeMesh(treeGeos[tm]));

/* ------------------------------------------------------------------ snow */
var SNOW_COUNT = 720;
var SNOW_R = 0.925;
var snow = [];
var snowPos = new Float32Array(SNOW_COUNT*3);
var snowSizeArr = new Float32Array(SNOW_COUNT);
var snowPosBuf = gl.createBuffer();
var snowSizeBuf = gl.createBuffer();

function randInSphere(R){
  var x,y,z;
  do{ x=Math.random()*2-1; y=Math.random()*2-1; z=Math.random()*2-1; }
  while(x*x+y*y+z*z > 1);
  return [x*R, y*R, z*R];
}
function respawn(s){
  for(var k=0;k<12;k++){
    var p=randInSphere(SNOW_R*0.97);
    if(p[1] > 0.30){ s.x=p[0]; s.y=p[1]; s.z=p[2]; break; }
  }
  s.vx=(Math.random()-0.5)*0.05;
  s.vy=-0.04-Math.random()*0.05;
  s.vz=(Math.random()-0.5)*0.05;
}
for(var si=0; si<SNOW_COUNT; si++){
  var sp = { x:0,y:0,z:0, vx:0,vy:0,vz:0, seed:Math.random()*Math.PI*2 };
  var p0 = randInSphere(SNOW_R*0.95);
  sp.x=p0[0]; sp.y=p0[1]; sp.z=p0[2];
  sp.vx=(Math.random()-0.5)*0.05; sp.vy=-0.05; sp.vz=(Math.random()-0.5)*0.05;
  snow.push(sp);
  snowSizeArr[si] = 0.013 + Math.random()*0.019;
}
gl.bindBuffer(gl.ARRAY_BUFFER, snowSizeBuf);
gl.bufferData(gl.ARRAY_BUFFER, snowSizeArr, gl.STATIC_DRAW);
gl.bindBuffer(gl.ARRAY_BUFFER, snowPosBuf);
gl.bufferData(gl.ARRAY_BUFFER, snowPos, gl.DYNAMIC_DRAW);

function floorY(x,z){
  var rr=Math.hypot(x,z);
  if(rr < MOUND.xr){
    var t=rr/MOUND.xr;
    return MOUND.yc + MOUND.yr*Math.sqrt(Math.max(0, 1-t*t));
  }
  return MOUND.yc;
}

var time = 0;
function updateSnow(dt){
  var t = time;
  for(var i=0;i<SNOW_COUNT;i++){
    var s = snow[i];
    s.vy -= 0.16*dt;
    s.vx += Math.sin(t*1.30 + s.seed)*0.06*dt;
    s.vz += Math.cos(t*1.05 + s.seed*1.7)*0.06*dt;
    var drag = Math.exp(-0.7*dt);
    s.vx *= drag; s.vz *= drag; s.vy *= Math.exp(-0.35*dt);
    s.x += s.vx*dt; s.y += s.vy*dt; s.z += s.vz*dt;

    var rr = Math.hypot(s.x, s.y, s.z);
    if(rr > SNOW_R){
      var kk = SNOW_R/rr;
      s.x*=kk; s.y*=kk; s.z*=kk;
      s.vx*=-0.25; s.vy*=-0.25; s.vz*=-0.25;
    }
    if(s.y < floorY(s.x, s.z) + 0.006) respawn(s);

    snowPos[i*3]=s.x; snowPos[i*3+1]=s.y; snowPos[i*3+2]=s.z;
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, snowPosBuf);
  gl.bufferSubData(gl.ARRAY_BUFFER, 0, snowPos);
}

/* -------------------------------------------------------------- painting */
function bindAttrib(loc, buf, size){
  if(loc < 0) return;
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 0, 0);
}
var viewMat = new Float32Array(16);
var projMat = new Float32Array(16);
var LIGHT = new Float32Array([0.46, 0.74, 0.50]);
var eye = [0,0,4];

function drawLit(mesh, alpha){
  gl.useProgram(litProg);
  gl.uniformMatrix4fv(litLoc.uView, false, viewMat);
  gl.uniformMatrix4fv(litLoc.uProj, false, projMat);
  gl.uniform3fv(litLoc.uLight, LIGHT);
  gl.uniform3fv(litLoc.uCam, eye);
  gl.uniform1f(litLoc.uAlpha, alpha);
  bindAttrib(litLoc.aPos, mesh.pos, 3);
  bindAttrib(litLoc.aNor, mesh.nor, 3);
  bindAttrib(litLoc.aCol, mesh.col, 3);
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, mesh.idx);
  gl.drawElements(gl.TRIANGLES, mesh.count, gl.UNSIGNED_SHORT, 0);
}
function drawGlass(mesh, alpha){
  gl.useProgram(glassProg);
  gl.uniformMatrix4fv(glassLoc.uView, false, viewMat);
  gl.uniformMatrix4fv(glassLoc.uProj, false, projMat);
  gl.uniform3fv(glassLoc.uLight, LIGHT);
  gl.uniform3fv(glassLoc.uCam, eye);
  gl.uniform1f(glassLoc.uAlpha, alpha);
  bindAttrib(glassLoc.aPos, mesh.pos, 3);
  bindAttrib(glassLoc.aNor, mesh.nor, 3);
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, mesh.idx);
  gl.drawElements(gl.TRIANGLES, mesh.count, gl.UNSIGNED_SHORT, 0);
}
function drawSnow(focal){
  gl.useProgram(pointProg);
  gl.uniformMatrix4fv(pointLoc.uView, false, viewMat);
  gl.uniformMatrix4fv(pointLoc.uProj, false, projMat);
  gl.uniform1f(pointLoc.uFocal, focal);
  bindAttrib(pointLoc.aPos, snowPosBuf, 3);
  bindAttrib(pointLoc.aSize, snowSizeBuf, 1);
  gl.drawArrays(gl.POINTS, 0, SNOW_COUNT);
}
function renderScene(focal){
  gl.clearColor(0,0,0,0);
  gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

  /* far inner shell of the glass, so contents appear refracted/behind it */
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  gl.depthMask(false);
  gl.cullFace(gl.FRONT);
  drawGlass(globeMesh, 0.40);

  /* opaque contents */
  gl.disable(gl.BLEND);
  gl.depthMask(true);
  gl.cullFace(gl.BACK);
  drawLit(baseMesh, 1.0);
  drawLit(moundMesh, 1.0);
  drawLit(mountainMesh, 1.0);
  for(var i=0;i<treeMeshes.length;i++) drawLit(treeMeshes[i], 1.0);

  /* snow */
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  gl.depthMask(false);
  drawSnow(focal);

  /* near shell of the glass */
  gl.cullFace(gl.BACK);
  drawGlass(globeMesh, 0.95);
  gl.cullFace(gl.BACK);

  gl.depthMask(true);
  gl.disable(gl.BLEND);
}

/* ------------------------------------------------------------- interaction */
var camYaw = 0.62, camPitch = 0.20, camDist = 3.9;
var eyeTarget = [0, -0.08, 0];
var wobble = 0;
var FOV = 45*Math.PI/180;

function resize(){
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  var w = Math.max(1, Math.round(canvas.clientWidth * dpr));
  var h = Math.max(1, Math.round(canvas.clientHeight * dpr));
  if(canvas.width !== w || canvas.height !== h){ canvas.width = w; canvas.height = h; }
  gl.viewport(0,0,w,h);
  return (h*0.5)/Math.tan(FOV*0.5);
}
var focal = resize();
window.addEventListener('resize', function(){ focal = resize(); });

function shakeGlobe(power){
  for(var i=0;i<snow.length;i++){
    var s=snow[i];
    var a=Math.random()*Math.PI*2;
    var m=0.55+Math.random()*0.75;
    s.vx += Math.cos(a)*m*power;
    s.vz += Math.sin(a)*m*power;
    s.vy += (0.45 + Math.random()*0.75)*power;
  }
  wobble = Math.min(1.4, wobble + power);
}

var dragging=false, lastX=0, lastY=0, moved=0, downTime=0;
canvas.addEventListener('pointerdown', function(e){
  dragging=true; moved=0; lastX=e.clientX; lastY=e.clientY; downTime=performance.now();
  if(canvas.setPointerCapture){ try{ canvas.setPointerCapture(e.pointerId); }catch(err){} }
});
canvas.addEventListener('pointermove', function(e){
  if(!dragging) return;
  var dx=e.clientX-lastX, dy=e.clientY-lastY;
  lastX=e.clientX; lastY=e.clientY;
  moved += Math.abs(dx)+Math.abs(dy);
  camYaw -= dx*0.0062;
  camPitch = Math.max(-0.38, Math.min(1.15, camPitch + dy*0.0052));
});
function endDrag(e){
  if(!dragging) return;
  dragging=false;
  if(moved < 7 && (performance.now()-downTime) < 420) shakeGlobe(1.0);
}
canvas.addEventListener('pointerup', endDrag);
canvas.addEventListener('pointercancel', function(){ dragging=false; });
canvas.addEventListener('wheel', function(e){
  e.preventDefault();
  camDist *= Math.exp(e.deltaY * 0.0011);
  camDist = Math.max(2.5, Math.min(7.2, camDist));
}, {passive:false});
canvas.addEventListener('contextmenu', function(e){ e.preventDefault(); });
document.getElementById('shakeBtn').addEventListener('click', function(){ shakeGlobe(1.15); });

/* ------------------------------------------------------------------- loop */
var last = (typeof performance!=='undefined' && performance.now) ? performance.now() : Date.now();
function frame(now){
  var dt = (now-last)/1000; last = now;
  if(!(dt > 0)) dt = 0.016;
  if(dt > 0.05) dt = 0.05;
  time += dt;

  updateSnow(dt);

  var cp = Math.cos(camPitch), sp2 = Math.sin(camPitch);
  eye[0] = camDist*cp*Math.sin(camYaw);
  eye[1] = eyeTarget[1] + camDist*sp2;
  eye[2] = camDist*cp*Math.cos(camYaw);
  if(wobble > 0.001){
    eye[0] += Math.sin(time*46)*wobble*0.045;
    eye[1] += Math.cos(time*39)*wobble*0.045;
    wobble *= Math.exp(-dt*3.1);
  } else { wobble = 0; }

  lookAt(viewMat, eye, eyeTarget, [0,1,0]);
  perspective(projMat, FOV, canvas.width/canvas.height, 0.1, 60);

  renderScene(focal);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

})();
</script>
